parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "status": {
      "type": "string",
      "description": "Status of the workflow execution"
    },
    "emailSent": {
      "type": "boolean",
      "description": "Whether the email was successfully sent"
    },
    "summary": {
      "type": "string",
      "description": "Brief summary of what was accomplished"
    },
    "sourcesCount": {
      "type": "number",
      "description": "Number of sources included in References"
    }
  }
}

{
  "type": "object",
  "properties": {
    "findings": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "fact": {
            "type": "string",
            "description": "The research finding or fact"
          },
          "source": {
            "type": "string",
            "description": "Source name or publication"
          },
          "url": {
            "type": "string",
            "description": "COMPLETE URL to the specific article"
          },
          "date": {
            "type": "string",
            "description": "Date of publication"
          },
          "institution": {
            "type": "string",
            "description": "Research institution or organization"
          }
        }
      }
    }
  }
}

{
  "type": "object",
  "properties": {
    "verifiedFacts": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "fact": {
            "type": "string",
            "description": "The verified fact"
          },
          "verified": {
            "type": "boolean",
            "description": "Whether the fact is verified (appears in 2+ sources)"
          },
          "sources": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "name": {
                  "type": "string",
                  "description": "Source name"
                },
                "url": {
                  "type": "string",
                  "description": "Complete URL to source"
                },
                "date": {
                  "type": "string",
                  "description": "Publication date"
                }
              }
            },
            "description": "List of sources with URLs that confirm this fact"
          }
        }
      }
    }
  }
}

{
  "type": "object",
  "properties": {
    "report": {
      "type": "string",
      "description": "Complete report with inline citations and References section"
    },
    "wordCount": {
      "type": "number",
      "description": "Word count of the report"
    },
    "referencesCount": {
      "type": "number",
      "description": "Number of references included"
    },
    "hasReferencesSection": {
      "type": "boolean",
      "description": "Confirms References section is included"
    }
  }
}

{
  "type": "object",
  "properties": {
    "htmlContent": {
      "type": "string",
      "description": "Complete HTML with clickable href links and styled References section"
    },
    "linkCount": {
      "type": "number",
      "description": "Number of clickable links created"
    },
    "hasClickableReferences": {
      "type": "boolean",
      "description": "Confirms all references have clickable links"
    }
  }
}
